jobs = {}

def create(job_id):
    jobs[job_id] = {"status": "queued", "error": None, "attempts": 0}

def get(job_id):
    return jobs[job_id]

def started(job_id):
    job = jobs[job_id]
    job["status"] = "running"
    job["error"] = None
    job["attempts"] += 1

def succeeded(job_id):
    jobs[job_id]["status"] = "done"

def failed(job_id, error):
    jobs[job_id]["status"] = "failed"
    jobs[job_id]["error"] = str(error)

