for state in ('queued', 'running', 'done'):
    store.jobs['a']['status'] = state
    before = service.snapshot('a')
    try:
        service.retry('a', forbidden)
    except ValueError:
        pass
    else:
        raise AssertionError('retry accepted ' + state)
    assert service.snapshot('a') == before
